import numpy as np

def cosine_similarity(vec1: np.ndarray, vec2: np.ndarray) -> float:
    """Compute cosine similarity between two vectors."""
    dot_product = np.dot(vec1, vec2)
    norm1 = np.linalg.norm(vec1)
    norm2 = np.linalg.norm(vec2)
    if norm1 == 0 or norm2 == 0:
        return 0.0
    return dot_product / (norm1 * norm2)

import numpy as np
from typing import List

class VectorStore:
    """Simple in-memory vector store for semantic search."""
    def __init__(self):
        self.vectors = []
        self.metadata = []

    def add(self, vector: np.ndarray, metadata: dict):
        self.vectors.append(vector)
        self.metadata.append(metadata)

    def search(self, query_vector: np.ndarray, top_k: int = 5) -> List[dict]:
        similarities = [cosine_similarity(query_vector, v) for v in self.vectors]
        indices = np.argsort(similarities)[::-1][:top_k]
        return [
            {"metadata": self.metadata[i], "score": similarities[i]}
            for i in indices
        ]

def chunk_text(text: str, chunk_size: int = 500, overlap: int = 50) -> List[str]:
    """Split text into overlapping chunks for embedding."""
    chunks = []
    start = 0
    while start < len(text):
        end = min(start + chunk_size, len(text))
        chunks.append(text[start:end])
        if end == len(text):
            break
        start = end - overlap
    return chunks

